using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class RegionalDomainTests
{
    static readonly EntityId Site=new("site:castle");
    internal static WorldSession Start(string person="person:nobunaga",ulong seed=1)=>new(NewGameWorld.Create(NewGameWorld.Scenario(HistoricalStartCatalog.Current),[],person,seed,historicalCatalog:HistoricalStartCatalog.Current,inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:WorkFollowup.Policy,economyPolicy:RegionalDomains.Policy));
    static EntityId Here(WorldSession s)=>s.DiagnosticSnapshot().Locations.Single(l=>l.Actor==s.PlayerControl).Site!.Value;
    static CommandResult Act(WorldSession s,TreasuryAction a,string? kind=null,long quantity=0,long amount=0,string? id=null)=>s.ManageHouseTreasury(new(new(id??"request:domain/"+s.Revision),a,Here(s),kind,quantity,amount),s.PlayerControl,s.Revision);
    static void Good(CommandResult r)=>Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);
    static void Advance(WorldSession s,long at){while(s.Seconds<at){long prior=s.Seconds;s.SetPaused(false);s.AdvanceTo(at,100000);Assert.True(s.Seconds>prior);}}
    static long Day(int y,int m,int d)=>(new DateOnly(y,m,d).DayNumber-new DateOnly(1560,1,1).DayNumber)*86400L;
    [Fact]public void AllThirtyCommunitiesHaveProfilesButUnownedRegionsHaveNoHouseAssets(){var s=Start();var w=s.DiagnosticSnapshot();Assert.Equal(30,w.Domains!.Profiles.Length);Assert.Equal(30,w.Communities!.Accounts.Length);Assert.Equal(30,w.Villages!.Organizations.Length);Assert.Equal(30,w.Materials!.Houses.Length);Assert.Contains(w.Domains.Profiles,p=>p.Owner==null);foreach(var p in w.Domains.Profiles.Where(p=>p.Owner==null)){Assert.Equal(0,p.HouseRice);Assert.Equal(0,p.InitialCash);Assert.Equal(0,w.Communities.Accounts.Single(a=>a.Site==p.Site).HouseRice);Assert.Equal(0,w.Materials.Houses.Single(h=>h.Site==p.Site).Wood);}Assert.Equal(500,s.HouseTreasuryView()!.HouseCash);}
    [Fact]public void FundingHouseAndLocalPurchaseKeepPrivateMoneySeparate(){var s=Start();Good(Act(s,TreasuryAction.Fund,amount:100));Assert.Equal(900,NewGameWork.Balance(s.DiagnosticSnapshot(),s.PlayerControl));Assert.Equal(600,s.HouseTreasuryView()!.HouseCash);Good(Act(s,TreasuryAction.Buy,"wood",10));Assert.Equal(560,s.HouseTreasuryView()!.HouseCash);Assert.Equal(30,s.HouseTreasuryView()!.Materials.Wood);Assert.Equal(900,NewGameWork.Balance(s.DiagnosticSnapshot(),s.PlayerControl));var e=s.DiagnosticSnapshot().Domains!.Entries.Last();Assert.NotNull(e.Quote);Assert.NotNull(e.Receipt);Assert.NotNull(e.Payment);Assert.Equal(e.Quote!.Id,e.Receipt!.Quote);Assert.Equal(e.Quote.Id,e.Payment!.Quote);}
    [Fact]public void BudgetCanDecreaseWithoutDeletingOldPurchases(){var s=Start();Good(Act(s,TreasuryAction.Buy,"wood",25));Good(Act(s,TreasuryAction.SetBudget,amount:50));Assert.Equal(0,s.HouseTreasuryView()!.Remaining);Assert.Equal(400,s.HouseTreasuryView()!.HouseCash);Assert.Equal(ResultCode.NotAvailable,Act(s,TreasuryAction.Buy,"wood",1).Code);}
    [Fact]public void NationwideMonthHasThirtyWorkshopAndFoodRecords(){var s=Start();Advance(s,Day(1560,2,1));Assert.Equal(30,s.DiagnosticSnapshot().Materials!.Months.Length);Assert.All(s.DiagnosticSnapshot().Communities!.Accounts,a=>Assert.Equal(1000,a.Consumed));}

    static readonly EntityId Head=new("person:shingen"),Kofu=new("site:kofu"),Agent=HistoricalHouseholdCatalog.Edition.People.Single().Id;
    static EntityId Grant(WorldSession s,int days=30){Good(s.ManageStewardship(new(new("request:domains-grant/"+s.Revision),StewardAction.Assign,Kofu,s.PlayerControl==Head?Agent:Head,Days:days,ReturnAddress:Kofu),s.PlayerControl,s.Revision));return s.DiagnosticSnapshot().Stewardship!.Grants.Last().Id;}
    static CommandResult Operate(WorldSession s,EntityId g)=>s.ManageStewardship(new(new("request:domains-water/"+s.Revision),StewardAction.Operate,Kofu,Grant:g,Operation:EconomyAction.ImproveWater,Amount:200),s.PlayerControl,s.Revision);
    static void HeadWater(WorldSession s){var site=Here(s);Good(s.ConsultVillage(new(new("request:domain-water-talk/"+s.Revision),VillageAction.ProposeWater,site,Amount:200),s.PlayerControl,s.Revision));var q=s.DiagnosticSnapshot().Villages!.Proposals.Last().Id;Good(s.ConsultVillage(new(new("request:domain-water-agree/"+s.Revision),VillageAction.Confirm,site,q),s.PlayerControl,s.Revision));Good(s.ConsultVillage(new(new("request:domain-water-start/"+s.Revision),VillageAction.Deliver,site,q,200),s.PlayerControl,s.Revision));Advance(s,s.Seconds+7*86400);}
    static void OpenAll(WorldSession s){foreach(var m in s.DiagnosticSnapshot().Messaging.Messages.Where(m=>m.RecipientId==s.PlayerControl.Value).ToArray())s.Open(s.PlayerControl,new(m.Id),s.Revision);}
    [Theory][InlineData(null,10)][InlineData("wood",10)][InlineData("weapons",2)]
    public void HousePurchaseConservesMerchantGoodsAndActualPayment(string? kind,long n){var s=Start();var w=s.DiagnosticSnapshot();var m=w.Trade!.Markets.Single(m=>m.Site==Here(s));Good(Act(s,TreasuryAction.Buy,kind,n));var after=s.DiagnosticSnapshot();var e=after.Domains!.Entries.Single();var now=after.Trade!.Markets.Single(m=>m.Site==Here(s));long Stock(TradeMarket x)=>MaterialMarkets.Stock(x,kind);Assert.Equal(Stock(m)-n,Stock(now));Assert.Equal(m.Cash+e.Payment!.Amount,now.Cash);Assert.Equal(500-e.Payment.Amount,s.HouseTreasuryView()!.HouseCash);Assert.Equal(1000,s.HouseTreasuryView()!.PrivateCash);if(kind==null)Assert.Equal(3000+n,s.CommunityEconomyView()!.Accounts.HouseRice);else Assert.Equal(kind=="wood"?20+n:10+n,kind=="wood"?s.HouseTreasuryView()!.Materials.Wood:s.HouseTreasuryView()!.Materials.Weapons);}
    [Theory][InlineData("invalid",1,0)][InlineData("wood",0,0)][InlineData("wood",1001,0)][InlineData("wood",1,1)][InlineData("weapons",40,0)]
    public void InvalidOrUnaffordablePurchaseIsAtomic(string kind,long n,long amount){var s=Start();var b=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,Act(s,TreasuryAction.Buy,kind,n,amount).Code);Assert.Equal(b,ContractJson.Write(s.DiagnosticSnapshot()));}
    [Theory][InlineData(-1)][InlineData(1001)]public void InvalidBudgetCannotMutate(long n){var s=Start();var b=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,Act(s,TreasuryAction.SetBudget,amount:n).Code);Assert.Equal(b,ContractJson.Write(s.DiagnosticSnapshot()));}
    [Fact]public void FundingCannotSpendMoneyReservedForPrivatePurchase(){var s=Start();Good(s.TradeRice(new(new("request:reserve-domain-money"),TradeAction.Quote,Here(s),Destination:Kofu,Amount:100){Commodity="wood"},s.PlayerControl,s.Revision));var d=s.DiagnosticSnapshot().Trade!.Deals.Single().Id;Good(s.TradeRice(new(new("request:accept-domain-money"),TradeAction.Accept,Here(s),d),s.PlayerControl,s.Revision));Assert.Equal(ResultCode.NotAvailable,Act(s,TreasuryAction.Fund,amount:700).Code);Good(Act(s,TreasuryAction.Fund,amount:600));Assert.Equal(0,s.HouseTreasuryView()!.PrivateCash);Assert.Equal(1100,s.HouseTreasuryView()!.HouseCash);}
    [Fact]public void HouseCannotConsumePrivatelyReservedStock(){var s=Start();Good(s.TradeRice(new(new("request:private-weapons"),TradeAction.Quote,Here(s),Destination:Kofu,Amount:20){Commodity="weapons"},s.PlayerControl,s.Revision));Good(s.TradeRice(new(new("request:private-weapons-accept"),TradeAction.Accept,Here(s),s.DiagnosticSnapshot().Trade!.Deals.Single().Id),s.PlayerControl,s.Revision));Good(Act(s,TreasuryAction.SetBudget,amount:1000));Good(Act(s,TreasuryAction.Fund,amount:500));Assert.Equal(ResultCode.NotAvailable,Act(s,TreasuryAction.Buy,"weapons",21).Code);Good(Act(s,TreasuryAction.Buy,"weapons",20));}
    [Fact]public void RepeatedStaleAndConflictingRequestsCannotSpendTwice(){var s=Start();long r=s.Revision;Good(Act(s,TreasuryAction.Buy,"wood",1,id:"request:domain-once"));Assert.Equal(ResultCode.AlreadyAccepted,Act(s,TreasuryAction.Buy,"wood",1,id:"request:domain-once").Code);Assert.Equal(ResultCode.IdPayloadConflict,Act(s,TreasuryAction.Buy,"wood",2,id:"request:domain-once").Code);Assert.Equal(ResultCode.StateChanged,s.ManageHouseTreasury(new(new("request:old-domain"),TreasuryAction.Buy,Here(s),"wood",1),s.PlayerControl,r).Code);Assert.Equal(21,s.HouseTreasuryView()!.Materials.Wood);}
    [Fact]public void RetainerNeedsGrantAndCannotChangeBudgetOrFundHouse(){var s=Start(Agent.Value);Assert.Null(s.HouseTreasuryView());Grant(s);Assert.False(s.HouseTreasuryView()!.CanSetBudget);Assert.Equal(ResultCode.NotAvailable,Act(s,TreasuryAction.SetBudget,amount:1000).Code);Assert.Equal(ResultCode.NotAvailable,Act(s,TreasuryAction.Fund,amount:1).Code);Good(Act(s,TreasuryAction.Buy,"wood",33));Assert.Equal(2,s.HouseTreasuryView()!.Remaining);Assert.Equal(ResultCode.NotAvailable,Act(s,TreasuryAction.Buy,"wood",1).Code);}
    [Fact]public void ExpiredGrantCannotSpendHouseMoney(){var s=Start(Agent.Value);Grant(s,1);Good(Act(s,TreasuryAction.Buy,"wood",1));Advance(s,86400);Assert.Null(s.HouseTreasuryView());Assert.Equal(ResultCode.NotAvailable,Act(s,TreasuryAction.Buy,"wood",1).Code);}
    [Fact]public void PlayerIsNeverAutopurchasedAndUnknownRegionsHaveNoController(){var s=Start();Advance(s,Day(1560,3,1));var w=s.DiagnosticSnapshot();Assert.DoesNotContain(w.Domains!.Decisions,d=>d.Actor==s.PlayerControl);foreach(var p in w.Domains.Profiles.Where(p=>p.Owner==null))Assert.DoesNotContain(w.Domains.Decisions,d=>d.Site==p.Site);Assert.Equal(500,s.HouseTreasuryView()!.HouseCash);}
    [Fact]public void NpcProcuresMissingWaterMaterialWithinRealHouseCash(){var s=Start();Advance(s,Day(1560,5,10));var w=s.DiagnosticSnapshot();Assert.Equal(130,w.Communities!.Accounts.Single(a=>a.Site==Kofu).Water);var buy=Assert.Single(w.Domains!.Entries,e=>e.Input.Site==Kofu);Assert.Equal("wood",buy.Input.Commodity);Assert.Equal(10,buy.Input.Quantity);Assert.InRange(buy.Payment!.Amount,1,200);Assert.Equal(30,w.Materials!.Houses.Single(h=>h.Site==Kofu).WoodUsed);Assert.Equal(1000,s.HouseTreasuryView()!.PrivateCash);}
    [Fact]public void BudgetZeroBlocksPurchaseWithoutBlockingFreeWait(){var s=Start(Head.Value);Good(Act(s,TreasuryAction.SetBudget,amount:0));HeadWater(s);HeadWater(s);Grant(s);Advance(s,17*86400);Assert.DoesNotContain(s.DiagnosticSnapshot().Domains!.Entries,e=>e.Input.Action==TreasuryAction.Buy);Assert.Equal(ResultCode.NotAvailable,Act(s,TreasuryAction.Buy,"wood",1).Code);Assert.Equal(500,s.HouseTreasuryView()!.HouseCash);}
    [Fact]public void RemoteOrOtherActorCannotAccessLiveTreasury(){var s=Start();Assert.Equal(ResultCode.NotAvailable,s.ManageHouseTreasury(new(new("request:remote-house"),TreasuryAction.Buy,Kofu,"wood",1),s.PlayerControl,s.Revision).Code);Assert.Equal(ResultCode.NotAvailable,s.ManageHouseTreasury(new(new("request:other-house"),TreasuryAction.Buy,Site,"wood",1),Head,s.Revision).Code);Good(s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:domain-trip","kyoto"),s.Revision));Advance(s,2);Assert.Null(s.HouseTreasuryView());}
    [Fact]public void ReportAndResendKeepOldCashMaterialAndBudgetObservations(){var s=Start(Agent.Value);var g=Grant(s);Good(s.ManageStewardship(new(new("request:domain-report"),StewardAction.Report,Kofu,Grant:g),s.PlayerControl,s.Revision));var p=s.DiagnosticSnapshot().Stewardship!.Papers.Single();Good(Act(s,TreasuryAction.Buy,"wood",10));Good(s.ManageStewardship(new(new("request:domain-resend"),StewardAction.ResendReport,Kofu,Grant:g,Report:p.Id),s.PlayerControl,s.Revision));var copy=s.DiagnosticSnapshot().Stewardship!.Papers.Last();Assert.Equal(p.Observation,copy.Observation);Assert.Equal(500,copy.Observation!.Regional!.HouseCash);Assert.Equal(20,copy.Observation.Regional.Materials.Wood);Assert.Equal(440,s.HouseTreasuryView()!.HouseCash);}
    [Fact]public void SealedReportsDoNotRevealCashUntilPhysicallyOpened(){var s=Start(Head.Value);Grant(s);Advance(s,86400);Assert.Empty(s.StewardshipView()!.Reports);Advance(s,86410);Assert.Empty(s.StewardshipView()!.Reports);OpenAll(s);Assert.NotNull(Assert.Single(s.StewardshipView()!.Reports).Observation!.Regional);}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)]public void ForgedProfilePaymentWorkshopOrDecisionCannotLoad(int which){var s=Start();Good(Act(s,TreasuryAction.Buy,"wood",1));Advance(s,Day(1560,2,1));var w=s.DiagnosticSnapshot();if(which==0)w.Domains=w.Domains! with{Profiles=[..w.Domains.Profiles.Select(p=>p with{InitialCash=99999})]};if(which==1)w.Domains=w.Domains! with{Entries=[..w.Domains.Entries.Select(e=>e with{Payment=e.Payment! with{Amount=0}})]};if(which==2)w.Materials=w.Materials! with{Months=[..w.Materials.Months.Select(m=>m with{WoodMade=999})]};if(which==3)w.Domains=w.Domains! with{Decisions=[..w.Domains.Decisions.Select(d=>d with{InputsHash="forged"})]};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact]public void OptimizedChangesAndFreshFullReplayProduceSameFuture(){var a=Start();Advance(a,Day(1560,2,1));Good(Act(a,TreasuryAction.Buy,"wood",4));var b=new WorldSession(ContractJson.Read<ContractWorld>(ContractJson.Write(a.DiagnosticSnapshot())));foreach(var s in new[]{a,b}){Good(Act(s,TreasuryAction.Fund,amount:25));Advance(s,Day(1560,3,1));}Assert.Equal(ContractJson.Write(a.DiagnosticSnapshot()),ContractJson.Write(b.DiagnosticSnapshot()));}
    [Fact]public void LegacyV8BytesCannotAcquireNewTreasuryOrReportFields(){var s=MaterialMarketTests.Start();var bytes=ContractJson.Write(s.DiagnosticSnapshot());Assert.DoesNotContain("Domains",System.Text.Encoding.UTF8.GetString(bytes));Assert.Equal(bytes,ContractJson.Write(new WorldSession(ContractJson.Read<ContractWorld>(bytes)).DiagnosticSnapshot()));Assert.Null(s.HouseTreasuryView());Assert.Equal(ResultCode.NotAvailable,Act(s,TreasuryAction.Buy,"wood",1).Code);var w=s.DiagnosticSnapshot();w.Domains=Start().DiagnosticSnapshot().Domains;Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)][InlineData(4)][InlineData(5)]
    public void ActualGenerationRecoveryPreservesNationwideMoneyPurchaseAndRevocation(int phase){var a=Start(Head.Value);EntityId? g=null;if(phase==0)Advance(a,Day(1560,2,1));if(phase==1)Good(Act(a,TreasuryAction.Fund,amount:100));if(phase==2)Good(Act(a,TreasuryAction.Buy,"wood",10));if(phase>=3){HeadWater(a);HeadWater(a);g=Grant(a);if(phase>=4)Advance(a,16*86400);if(phase==5){Good(a.ManageStewardship(new(new("request:domains-cancel"),StewardAction.Revoke,Kofu,Grant:g),a.PlayerControl,a.Revision));Advance(a,a.Seconds+5);}}a.SetPaused(true);var w=a.DiagnosticSnapshot();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"domains-"+Guid.NewGuid().ToString("N")),w.Definitions);Assert.True(store.Save(a,"domains",w.WorldId).Published);var host=new WorldSessionHost(Start());Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("domains"),host.Current,host.Current.Revision));var b=host.Current;Assert.Equal(ContractJson.Write(a.HouseTreasuryView()),ContractJson.Write(b.HouseTreasuryView()));Assert.Equal(ContractJson.Write(a.StewardshipView()),ContractJson.Write(b.StewardshipView()));var dir=Environment.GetEnvironmentVariable("HAKUTAI_WORLD_CLASH_QA_DIR");if(!string.IsNullOrEmpty(dir)){Directory.CreateDirectory(dir);File.WriteAllBytes(Path.Combine(dir,"domains-"+phase+".before.json"),ContractJson.Write(a.DiagnosticSnapshot()));File.WriteAllBytes(Path.Combine(dir,"domains-"+phase+".restored.json"),ContractJson.Write(b.DiagnosticSnapshot()));}foreach(var s in new[]{a,b}){Good(Act(s,TreasuryAction.SetBudget,amount:100));Advance(s,s.Seconds+33*86400);}Assert.Equal(ContractJson.Write(a.DiagnosticSnapshot()),ContractJson.Write(b.DiagnosticSnapshot()));}

    [Fact]public void PhysicalRevocationStopsAgentProcurementBeforeNextDay(){var s=Start(Head.Value);HeadWater(s);HeadWater(s);var g=Grant(s);Good(s.ManageStewardship(new(new("request:stop-domain-procurement"),StewardAction.Revoke,Kofu,Grant:g),s.PlayerControl,s.Revision));Assert.Empty(s.DiagnosticSnapshot().Stewardship!.Receipts);Advance(s,s.Seconds+5);Assert.Single(s.DiagnosticSnapshot().Stewardship!.Receipts);Advance(s,17*86400);Assert.DoesNotContain(s.DiagnosticSnapshot().Domains!.Entries,e=>e.Input.Action==TreasuryAction.Buy);Assert.Equal(500,s.HouseTreasuryView()!.HouseCash);}
    [Fact]public void AbsentHeadWithoutDelegateWaitsRatherThanRemoteShopping(){var s=Start(Head.Value);HeadWater(s);HeadWater(s);Good(s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:absent-domain-head","castle"),s.Revision));Advance(s,Day(1560,2,1));var w=s.DiagnosticSnapshot();Assert.DoesNotContain(w.Domains!.Entries,e=>e.Input.Site==Kofu);Assert.DoesNotContain(w.Domains.Decisions,d=>d.Site==Kofu&&d.Quantity>0);Assert.Null(s.HouseTreasuryView());}
    [Fact]public void MonthlyBudgetResetsWithCalendarWithoutCreatingCash(){var s=Start();Good(Act(s,TreasuryAction.Buy,"wood",50));Assert.Equal(0,s.HouseTreasuryView()!.Remaining);Advance(s,Day(1560,2,1));Assert.Equal(200,s.HouseTreasuryView()!.Remaining);Assert.Equal(300,s.HouseTreasuryView()!.HouseCash);Good(Act(s,TreasuryAction.Buy,"wood",10));}
    [Fact]public void RaisingBudgetDoesNotCreateHouseMoney(){var s=Start();Good(Act(s,TreasuryAction.SetBudget,amount:1000));Assert.Equal(ResultCode.NotAvailable,Act(s,TreasuryAction.Buy,"weapons",21).Code);Good(Act(s,TreasuryAction.Buy,"weapons",20));Assert.Equal(0,s.HouseTreasuryView()!.HouseCash);Assert.Equal(ResultCode.NotAvailable,Act(s,TreasuryAction.Buy,"wood",1).Code);}
    [Fact]public void NpcHungerProcurementUsesFiniteCashAndPrecedesTimber(){var s=Start(Head.Value,seed:37);Advance(s,Day(1563,9,1));Grant(s);Advance(s,s.Seconds+86400);var w=s.DiagnosticSnapshot();Assert.Contains(w.Domains!.Entries,e=>e.Actor!=s.PlayerControl&&e.Input.Commodity==null);Assert.All(w.Domains.Entries.Where(e=>e.Input.Action==TreasuryAction.Buy),e=>Assert.InRange(e.Payment!.Amount,1,200));Assert.All(w.Domains.Profiles.Where(p=>p.Owner!=null),p=>Assert.True(500-w.Domains.Entries.Where(e=>e.Input.Site==p.Site&&e.Input.Action==TreasuryAction.Buy).Sum(e=>e.Payment!.Amount)>=0));}
    [Fact]public void NormalCampaignProfileEnablesExplicitV9WithLegacyModules(){var store=new NewCampaignStore(Path.Combine(Path.GetTempPath(),"domain-profile-"+Guid.NewGuid().ToString("N")));var p=store.New(NewGameWorld.Scenario(HistoricalStartCatalog.Current),[],"person:nobunaga",1,NewGameWorld.CompactPersonalAuthority,HistoricalStartCatalog.Current,NewGameNpcRoutine.Policy,LocalInspectionFindings.Policy,WorkFollowup.Policy,null,VoyageExpense.Standard,NpcArmies.CompactCombatPolicy,RegionalDomains.Policy,PersonalCompanions.RetainerReleasePolicy,TruceNegotiations.Policy,PrivateInformation.Policy,PrivateStanddown.Policy);var s=new WorldSession(NewCampaignStore.Build(store.Read(p.Instance)));Assert.NotNull(s.StewardshipView());Assert.NotNull(s.HouseTreasuryView());Assert.Equal(30,s.DiagnosticSnapshot().Communities!.Accounts.Length);}

    [Fact]public void ReceiptIdsCannotCollideWithExistingPrivateContracts(){var s=Start();string id="request:house-child-collision";var child=new EntityId("quote:house/"+ContractJson.Hash(System.Text.Encoding.UTF8.GetBytes(id)));Good(s.TradeRice(new(child,TradeAction.Quote,Here(s),Destination:Kofu,Amount:1){Commodity="wood"},s.PlayerControl,s.Revision));var before=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,Act(s,TreasuryAction.Buy,"wood",1,id:id).Code);Assert.Equal(before,ContractJson.Write(s.DiagnosticSnapshot()));}
    [Fact]public void ExistingUserIdCannotPreventNextNpcProcurementTurn(){var s=Start();string claimed="decision:house-procure/site/kofu/m18722";Good(s.TradeRice(new(new(claimed),TradeAction.Quote,Here(s),Destination:Kofu,Amount:1){Commodity="wood"},s.PlayerControl,s.Revision));Advance(s,Day(1560,2,1));Assert.Contains(s.DiagnosticSnapshot().Domains!.Decisions,d=>d.Site==Kofu&&d.Id.Value==claimed+"/n1");new WorldSession(s.DiagnosticSnapshot());}
}
